<?php require 'includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("INSERT INTO expenses(title,category,amount,payment_method,notes) VALUES(?,?,?,?,?)");$s->execute([$_POST['title'],$_POST['category'],$_POST['amount'],$_POST['payment_method'],$_POST['notes']]);header('Location: expenses.php');exit;}
$rows=$pdo->query("SELECT * FROM expenses ORDER BY created_at DESC LIMIT 100")->fetchAll();
?><h1>Expenses</h1><div class="panel"><form method="post"><div class="row3"><input name="title" placeholder="Expense title" required><input name="category" placeholder="Category"><input name="amount" type="number" step=".01" placeholder="Amount" required></div><div class="row"><select name="payment_method"><option>cash</option><option>mpesa</option><option>bank</option></select><input name="notes" placeholder="Notes"></div><button>Save Expense</button></form></div>
<div class="panel"><table><tr><th>Date</th><th>Title</th><th>Category</th><th>Method</th><th>Amount</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['created_at']?></td><td><?=e($r['title'])?></td><td><?=e($r['category'])?></td><td><?=e($r['payment_method'])?></td><td>KSh <?=money($r['amount'])?></td></tr><?php endforeach;?></table></div><?php require 'includes/footer.php';?>